const body = ($input.first().json.body) || $input.first().json || [];
const pages = Array.isArray(body) ? body : (body.pages || []);
const all = [];
(function flat(arr){ for (const p of (arr||[])) { all.push(p); if (p.pages) flat(p.pages); } })(pages);
const page = all.find(p => p.id === 'q7wz-44812');
const rules_md = (page && page.content) ? String(page.content) : '';
const rules_present = !!rules_md && rules_md.trim().length > 50;
const date_edited = page ? (page.date_edited || page.date_updated || null) : null;
return [{ json: { rules_md, rules_present, date_edited, page_found: !!page } }];

const inp = $input.first().json;
const rules = inp.rules_md;
const sha = inp.rules_sha256;
const CONV = 7;

const framing = [
  '# Tożsamość i kontrakt techniczny (stały)',
  'Jesteś uniwersalnym agentem Haxe uruchamianym do jednego konkretnego zadania w ClickUp. Poniżej masz globalne zasady firmy (utrzymywane w ClickUp jako jedyne źródło prawdy) oraz stały kontrakt techniczny formatu odpowiedzi. Szczegóły zadania, preferencje osoby zlecającej, komentarze i ewentualne obrazy wejściowe otrzymasz w wiadomości użytkownika.'
].join('\n');

const contract = [
  '# Format odpowiedzi (kontrakt techniczny — OBOWIĄZKOWY)',
  'Twoją finalną wiadomością zwróć WYŁĄCZNIE tablicę JSON bloków — PIERWSZY znak wiadomości to „[”, OSTATNI to „]”. NIE poprzedzaj tablicy żadnym zdaniem wprowadzającym (np. „Gotowe.”, „Plansza gotowa. Poniżej finalna odpowiedź.”) ani nie dodawaj nic po tablicy — wszelkie wstępy, komentarze i podsumowania umieść WEWNĄTRZ bloków text. Każdy znak poza tablicą jest ODRZUCANY i psuje dostarczenie obrazów. Bez ogrodzenia markdown. Każdy element tablicy to jeden z bloków:',
  '  { "type": "text", "md": "…treść markdown po polsku…" }',
  '  { "type": "image", "mode": "generate", "ref": "<file_id zwrócony przez narzędzie generate_image w TEJ sesji>", "caption": "…", "alt": "…" }',
  '  { "type": "image", "mode": "embed_input", "ref": "<ref z sekcji Załączone obrazy w wiadomości>", "caption": "…", "alt": "…" }',
  'Zasady:',
  '- Treść umieszczaj w blokach text (markdown: nagłówki, listy, tabele, pogrubienia). Zachowuj miękką strukturę WEWNĄTRZ bloków text, pomijając puste sekcje: "## Wyniki", "## Pytania do zlecającego", "## Decyzje i kompromisy", a na końcu "## Sugestie do procesu".',
  '- NOWY obraz tworzysz WYŁĄCZNIE wywołując narzędzie generate_image (patrz sekcja Narzędzia). Narzędzie zwraca file_id wygenerowanego obrazu. Aby pokazać ten obraz w odpowiedzi, wstaw blok { "type":"image", "mode":"generate", "ref":"<to file_id>", … } z file_id DOKŁADNIE jak zwróciło narzędzie. NIE umieszczaj w bloku pola "prompt" — obraz jest już wygenerowany; sam prompt bez wywołania narzędzia NIE utworzy obrazu. NIGDY nie wstawiaj file_id, którego narzędzie nie zwróciło w tej sesji.',
  '- Blok embed_input wstawia ISTNIEJĄCY obraz załączony do zadania (pole ref dokładnie jak w sekcji Załączone obrazy) — nie służy do nowych obrazów.',
  '- Pliki biurowe (xlsx, docx, pptx, pdf): twórz je odpowiednią umiejętnością i ZAPISZ do wyjść sesji. NIE umieszczaj ich w blokach JSON ani nie podawaj ich file_id — system automatycznie dołączy każdy taki plik jako załącznik do komentarza ClickUp. W bloku text WSPOMNIJ o pliku (nazwa + co zawiera), aby odbiorca wiedział, co dostał. Nie twierdź, że nie możesz załączyć pliku — możesz, przez zapis do wyjść sesji.',
  '- Bloki renderowane są w kolejności tablicy. Jeśli obrazy nie są potrzebne, zwróć same bloki text.'
].join('\n');

const toolsDesc = [
  '# Narzędzia i umiejętności',
  '- Wyszukiwanie w sieci (web_search) jest wbudowane — używaj go, gdy zadanie wymaga aktualnych lub zewnętrznych informacji. Korzystaj z równoległych zapytań i syntezy; NIGDY nie umieszczaj danych osobowych w treści zapytania.',
  '- Generowanie obrazów: aby utworzyć NOWY obraz, WYWOŁAJ narzędzie generate_image z parametrami { prompt (opis obrazu), aspect_ratio (np. "1:1"), opcjonalnie reference_file_ids (gdy chcesz wierności realnemu produktowi z załączonego zdjęcia), opcjonalnie size "SZERxWYS" w pikselach TYLKO gdy użytkownik prosi o konkretną rozdzielczość }. Narzędzie wykona się w tle i zwróci file_id; ten file_id wstaw w bloku image (mode:generate, ref:file_id) w finalnej odpowiedzi, aby obraz został dostarczony. Generuj obraz tylko gdy zadanie tego wymaga.',
  '- Umiejętności dokumentowe (docx, xlsx, pptx, pdf): używaj ich, gdy zadanie wymaga wygenerowania pliku biurowego, i zapisz wynik do wyjść sesji; system dołączy go automatycznie jako załącznik do komentarza (nie podawaj file_id pliku w odpowiedzi).', '- Wyszukiwanie powiązanego kontekstu w ClickUp (zakres uprawnień osoby zlecającej): jeśli masz dostępne narzędzia clickup_* (np. clickup_search, clickup_filter_tasks, clickup_get_task, clickup_get_task_comments, clickup_get_workspace_hierarchy, clickup_get_document_pages, clickup_get_custom_fields), używaj ich z własnej inicjatywy, aby znaleźć POWIĄZANE zadania, dokumenty, komentarze i pola niestandardowe istotne dla bieżącego zadania. Te narzędzia są ograniczone do uprawnień osoby, która Cię uruchomiła (widzisz wyłącznie to, co ona widzi w ClickUp) i służą wyłącznie do ODCZYTU — nie twórz ani nie modyfikuj niczego w ClickUp. Kontekst samego zadania wyzwalającego masz już w wiadomości; narzędzia clickup_* służą do szukania DODATKOWYCH powiązanych informacji. Jeśli narzędzia clickup_* nie są dostępne, pracuj na podstawie dostarczonego kontekstu i nie zgłaszaj tego jako błędu.', '- Ekstrakcja zawartości załączników (extract_clickup_task): narzędzia clickup_* zwracają opisy, komentarze i pola, ale NIE treść załączonych plików. Gdy powiązane zadanie ma załączniki (dokumenty, obrazy), których treść jest istotna dla bieżącego zadania, WYWOŁAJ extract_clickup_task z { clickup_task_id } tego zadania — zwróci wyekstrahowaną treść dokumentów (tekst) oraz obrazy (jako wizję), wyłącznie w zakresie Twoich uprawnień. Najpierw ROZPOZNAJ przez clickup_* co warto pobrać, potem ekstrahuj tylko istotne zadania (nie ekstrahuj masowo). Jeśli nie masz dostępu do zadania, narzędzie zwróci informację o braku dostępu — uszanuj to.'
].join('\n');

const provenance = '<!-- HAXE-AGENT-PROVENANCE rules_sha256=' + sha + ' conventions_version=' + CONV + ' source=clickup:q7wz-44812 -->';

const system = [framing, '', '# Globalne zasady działania agentów (źródło: ClickUp — jedyne źródło prawdy)', '', rules, '', contract, '', toolsDesc, '', provenance].join('\n');

// ADR-055 (Block 5.3): generowanie obrazów to teraz narzędzie na samodzielnie hostowanym serwerze MCP
// (haxe_image), a nie narzędzie custom po stronie klienta. mcp_servers deklaruje endpoint BEZ pola auth —
// bearer jest dołączany per sesję przez Anthropic Vault (config.image_mcp_vault_id) w Execute Agent Session (v1).
// Sparowany mcp_toolset z permission_policy=always_allow pozwala harnessowi wywołać generate_image
// w-harnessie (agent.mcp_tool_use), więc obraz nigdy nie wchodzi w pętlę pause/resume.
// CONV=3 (Block 6): kontrakt obrazów poprawiony — agent MUSI wywołać generate_image i odwołać się do
// zwróconego file_id (zamiast emitować blok generate z promptem, który na lane managed nie jest realizowany). ADR-054 (Block 3): drugi serwer MCP 'clickup' (mcp.clickup.com/mcp) + sparowany mcp_toolset READ-ONLY (default_config.enabled=false, dozwolone tylko narzędzia odczytu/discovery przez configs) — token MCP-OAuth dołączany per sesję z Anthropic Vault (clickup_mcp_vault_id) w Execute Agent Session; brak czytelnego dla OAuth zakresu read-only, więc read-only egzekwowany allowlistą. Każde dozwolone narzędzie ma własne permission_policy always_allow (API domyślnie ustawia always_ask na default_config). CONV=5 wymusza re-sync. CONV=7 (2026-06-24): wzmocniono zakaz tekstu/preambuly poza tablica blokow — model na zadaniu 869dux9ne dodal zdanie wprowadzajace przed [...], przez co render odrzucil blok obrazu (parse-fallback).
const mcp_servers = [ { type: 'url', url: 'https://agents.haxe.ai/mcp/haxe-image-gen', name: 'haxe_image' }, { type: 'url', url: 'https://mcp.clickup.com/mcp', name: 'clickup' } ];

const extract_clickup_task_tool = { type: 'custom', name: 'extract_clickup_task', description: 'Pobiera i ekstrahuje tresc zalacznikow zadania ClickUp (dokumenty -> tekst, obrazy -> wizja), w zakresie uprawnien osoby ktora uruchomila agenta. Uzyj po znalezieniu powiazanego zadania narzedziami clickup_*, gdy tresc jego zalacznikow jest istotna (narzedzia clickup_* nie zwracaja tresci plikow). Zadanie spoza Twoich uprawnien -> zwroci brak dostepu (nie obchodz tego). Tylko odczyt.', input_schema: { type: 'object', properties: { clickup_task_id: { type: 'string', description: 'Identyfikator zadania ClickUp, ktorego zalaczniki maja zostac wyekstrahowane.' } }, required: ['clickup_task_id'] } };
const tools = [
  { type: 'agent_toolset_20260401' },
  { type: 'mcp_toolset', mcp_server_name: 'haxe_image', default_config: { enabled: true, permission_policy: { type: 'always_allow' } } }, { type: 'mcp_toolset', mcp_server_name: 'clickup', default_config: { enabled: false }, configs: ['clickup_get_workspace_hierarchy','clickup_search','clickup_filter_tasks','clickup_get_task','clickup_get_task_comments','clickup_get_threaded_comments','clickup_get_custom_fields','clickup_get_document_pages','clickup_list_document_pages','clickup_get_folder','clickup_get_list','clickup_get_workspace_members','clickup_find_member_by_name','clickup_resolve_assignees'].map(function(n){ return { name: n, enabled: true, permission_policy: { type: 'always_allow' } }; }) }, extract_clickup_task_tool
];
const skills = [
  { type: 'anthropic', skill_id: 'docx', version: 'latest' },
  { type: 'anthropic', skill_id: 'xlsx', version: 'latest' },
  { type: 'anthropic', skill_id: 'pptx', version: 'latest' },
  { type: 'anthropic', skill_id: 'pdf', version: 'latest' }
];

return [{ json: { system, rules_sha256: sha, conventions_version: CONV, tools, skills, mcp_servers, system_len: system.length } }];

const bs = $('Build System').first().json;
const curSha = bs.rules_sha256, curConv = bs.conventions_version;
let force = false;
try { const wc = $('When Called').first().json; if (wc && (wc.force === true || wc.force === 'true')) force = true; } catch(e){}
return $input.all().map(it => {
  const j = it.json;
  let action;
  if (!j.agent_id) action = 'create';
  else if (force) action = 'update';
  else if (j.rules_sha256 !== curSha || (j.conventions_version || 0) !== curConv) action = 'update';
  else action = 'skip';
  return { json: Object.assign({}, j, { action: action, needs_write: action !== 'skip' }) };
});
